public final class ClaimStatusMachine {

    public enum Status {
        OPEN,
        IN_REVIEW,
        CLOSED
    }

    private ClaimStatusMachine() {
    }

    public static boolean canTransition(Status current, Status target) {
        Objects.requireNonNull(current, "current");
        Objects.requireNonNull(target, "target");
        // TODO: same status is a no-op; CLOSED is terminal;
        // OPEN may only move to IN_REVIEW; IN_REVIEW may move to OPEN or CLOSED.
        return false;
    }

    public static Status transition(Status current, Status target) {
        Objects.requireNonNull(current, "current");
        Objects.requireNonNull(target, "target");
        // TODO: return target when the move is allowed. Otherwise throw IllegalStateException
        // whose message contains both status names.
        return target;
    }
}

