import java.util.Objects;

public final class ClaimStatusMachine {

    public enum Status {
        OPEN,
        IN_REVIEW,
        CLOSED
    }

    public record Transition(Status from, Status to, String note) {
    }

    private ClaimStatusMachine() {
    }

    public static boolean canTransition(Status current, Status target) {
        Objects.requireNonNull(current, "current");
        Objects.requireNonNull(target, "target");
        if (current == target) {
            return true;
        }
        if (current == Status.CLOSED) {
            return false;
        }
        if (current == Status.OPEN) {
            return target == Status.IN_REVIEW;
        }
        return target == Status.OPEN || target == Status.CLOSED;
    }

    public static Status transition(Status current, Status target) {
        Objects.requireNonNull(current, "current");
        Objects.requireNonNull(target, "target");
        if (!canTransition(current, target)) {
            throw new IllegalStateException(
                    "Illegal claim status transition: " + current + " -> " + target);
        }
        return target;
    }

    public static Transition transition(Status current, Status target, String note) {
        Objects.requireNonNull(current, "current");
        Objects.requireNonNull(target, "target");
        transition(current, target);
        String cleaned = note == null ? "" : note.trim();
        if (target == Status.OPEN && cleaned.isEmpty()) {
            throw new IllegalArgumentException("A note is required when reopening a claim.");
        }
        return new Transition(current, target, cleaned);
    }
}
